let LANG = (() => { try { return localStorage.getItem('elo-lang') || 'en'; } catch { return 'en'; } })();
function t(key, vars) {
  let s = (I18N[LANG] && I18N[LANG][key]) || I18N.en[key] || key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(v);
  return s;
}
